#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>

struct partage { int compteur; char message[32]; };

int main(void) {
    int shmid = shmget(IPC_PRIVATE, sizeof(struct partage), IPC_CREAT | 0600);
    if (shmid == -1) { perror("shmget"); exit(EXIT_FAILURE); }

    struct partage *d = (struct partage *) shmat(shmid, NULL, 0);
    if (d == (void *) -1) { perror("shmat"); exit(EXIT_FAILURE); }

    /* le pere initialise le segment AVANT le fork */
    d->compteur = 10;
    strcpy(d->message, "init");

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        /* le fils ecrit dans le segment partage, puis se termine */
        d->compteur += 5;
        strcpy(d->message, "fils ici");
        shmdt(d);
        exit(EXIT_SUCCESS);
    }

    /* wait() garantit que l'ecriture du fils est terminee : pas de course */
    wait(NULL);
    printf("compteur = %d\n", d->compteur);
    printf("message = %s\n", d->message);

    shmdt(d);
    shmctl(shmid, IPC_RMID, NULL);
